import { createHash } from "crypto";

/**
 * Generate a stable, deterministic id for a graveyard entity.
 *
 * Given the same `type` and `ref`, this function always produces the same id.
 * This stability allows the UI to track "banished" entities across re-scans of
 * the same repository.
 *
 * The id is a 16-character hex string (64 bits), generated by hashing
 * `type + ":" + ref` with SHA-1 and taking the first 16 characters. This
 * provides sufficient collision resistance at repository scale (thousands of
 * entities per repo).
 *
 * @param type - The entity type ("tombstone", "zombie", "ghost", "crypt").
 * @param ref - The entity reference (file path, branch name, etc.).
 * @returns A 16-character lowercase hex string.
 *
 * @example
 * entityId("tombstone", "src/utils/legacy.ts")
 * // => "a3f5b2c1d4e6f7a8"
 */
export function entityId(type: string, ref: string): string {
  return createHash("sha1")
    .update(`${type}:${ref}`)
    .digest("hex")
    .slice(0, 16);
}
